// pool.hpp -- prototype: chunked bump allocator + intrusive ref-counted smart pointers.
//   generated by Claud.ai
//
// C++17, Linux only, single-threaded, T must be trivially destructible.
//
//   Pool<T>::Factory   public interface; owns the Allocator and all memory
//   Pool<T>::Allocator manages chunks (bump allocation, recycle cache, mmap/munmap)
//   Pool<T>::Chunk     ChunkBytes-aligned block: small header + array of Slots
//   Pool<T>::Slot      storage for one T plus its reference count
//   Pool<T>::Ptr       owning, ref-counted, immutable (const T) smart pointer
//   Pool<T>::WeakPtr   non-counting handle; converts to a counted Ptr on demand
//
// Lifetime rules:
//   * Every Ptr/WeakPtr must be gone before its Factory is destroyed.
//   * A WeakPtr is only valid while some Ptr to the same slot is alive.
#pragma once

#include <sys/mman.h>

#include <cassert>
#include <cstddef>
#include <cstdint>
#include <new>
#include <type_traits>
#include <utility>
#include <vector>

namespace scabbard {
namespace rtl {

// Kept at namespace scope (aliased inside Pool) so they can be used in default
// arguments of Pool's nested classes without NSDMI-ordering problems.
struct PoolOptions {
  // Freed chunks kept for reuse instead of being munmap'd. This is your "K" and
  // the memory floor: roughly K * ChunkBytes stays resident between bursts.
  std::size_t max_cached_chunks = 64;
  // When the cache is empty, map this many chunks with one mmap call.
  std::size_t refill_batch = 4;
  // Ask for transparent huge pages on new mappings (best effort).
  bool use_huge_pages = true;
  // false => skip munmap in ~Allocator and let the OS reclaim at process exit.
  bool unmap_on_destroy = true;
};

struct PoolStats {
  std::size_t chunks_in_use = 0;   // chunks that currently hold live slots (or are being filled)
  std::size_t chunks_cached = 0;   // free chunks waiting for reuse
  std::uint64_t mmap_calls = 0;    // net new mappings requested from the OS
  std::uint64_t munmap_calls = 0;  // chunks (or slivers) returned to the OS
  std::uint64_t chunks_mapped = 0; // total chunks ever obtained from the OS
  std::uint64_t chunk_reuses = 0;  // chunks served from the recycle cache
};

template <class T, std::size_t ChunkBytes = (std::size_t(1) << 21)>
struct Pool {
  static_assert(std::is_trivially_destructible_v<T>,
                "Pool<T>: T must be trivially destructible (slots are never destroyed)");
  static_assert((ChunkBytes & (ChunkBytes - 1)) == 0 && ChunkBytes >= 4096,
                "Pool<T>: ChunkBytes must be a power of two >= 4096");

  class Ptr;
  class WeakPtr;
  class Allocator;
  class Factory;

  using value_type = T;
  using Options = PoolOptions;
  using Stats = PoolStats;

  // ------------------------------------------------------------------ Slot
  struct Slot {
    alignas(T) unsigned char storage[sizeof(T)];  // MUST stay first: Slot* == T*
    std::uint32_t refs;
  };

  // ----------------------------------------------------------------- Chunk
  struct Chunk {
    Allocator* owner;
    Chunk* prev;  // intrusive list of in-use chunks (so the Allocator can free
    Chunk* next;  // stragglers on destruction)
    std::uint32_t live;  // slots with refs > 0, plus 1 while this is the chunk being filled

    static Chunk* of(const Slot* s) noexcept {
      return reinterpret_cast<Chunk*>(reinterpret_cast<std::uintptr_t>(s) &
                                      ~(std::uintptr_t(ChunkBytes) - 1));
    }
    Slot* slots() noexcept {
      return reinterpret_cast<Slot*>(reinterpret_cast<unsigned char*>(this) + kSlotsOffset);
    }
    // Called when a slot's refcount reaches zero.
    void retire_slot() noexcept {
      if (--live == 0) owner->release_chunk(this);
    }
  };

  static constexpr std::size_t kSlotsOffset =
      (sizeof(Chunk) + alignof(Slot) - 1) / alignof(Slot) * alignof(Slot);
  static constexpr std::size_t kSlotsPerChunk = (ChunkBytes - kSlotsOffset) / sizeof(Slot);

  static_assert(kSlotsPerChunk >= 1, "Pool<T>: ChunkBytes too small for T");
  static_assert(std::is_standard_layout_v<Slot> && offsetof(Slot, storage) == 0,
                "Pool<T>: Slot layout assumption violated");

  // ------------------------------------------------------------------- Ptr
  class Ptr {
   public:
    Ptr() noexcept = default;
    Ptr(std::nullptr_t) noexcept {}
    Ptr(const Ptr& o) noexcept : s_(o.s_) {
      if (s_) ++s_->refs;
    }
    Ptr(Ptr&& o) noexcept : s_(o.s_) { o.s_ = nullptr; }
    // Implicit on purpose: passing a WeakPtr where a Ptr is required upgrades it
    // (and bumps the count) right there.
    Ptr(const WeakPtr& w) noexcept : s_(w.s_) {
      if (s_) ++s_->refs;
    }
    ~Ptr() { drop(); }

    Ptr& operator=(const Ptr& o) noexcept {
      if (o.s_) ++o.s_->refs;  // increment first => self-assignment safe
      drop();
      s_ = o.s_;
      return *this;
    }
    Ptr& operator=(Ptr&& o) noexcept {
      if (this != &o) {
        drop();
        s_ = o.s_;
        o.s_ = nullptr;
      }
      return *this;
    }

    void reset() noexcept {
      drop();
      s_ = nullptr;
    }
    void swap(Ptr& o) noexcept { std::swap(s_, o.s_); }

    const T* get() const noexcept { return reinterpret_cast<const T*>(s_); }
    const T& operator*() const noexcept { return *get(); }
    const T* operator->() const noexcept { return get(); }
    explicit operator bool() const noexcept { return s_ != nullptr; }
    std::uint32_t use_count() const noexcept { return s_ ? s_->refs : 0; }

    WeakPtr weak() const noexcept { return WeakPtr(*this); }

    friend bool operator==(const Ptr& a, const Ptr& b) noexcept { return a.s_ == b.s_; }
    friend bool operator!=(const Ptr& a, const Ptr& b) noexcept { return a.s_ != b.s_; }

    class less {
    public:
      bool operator () (const Ptr& l, const Ptr& r) const { return *l < *r; }
    };
    // inverse of less for use with std::priority_queue (yields a min-heap).
    // Uses a strict ordering (r < l) rather than !(l < r), which is not a valid comparator.
    class priority_less {
    public:
      bool operator () (const Ptr& l, const Ptr& r) const { return *r < *l; }
    };

   private:
    friend Factory;
    friend WeakPtr;
    explicit Ptr(Slot* adopt) noexcept : s_(adopt) {}  // adopts an existing reference

    void drop() noexcept {
      if (s_ && --s_->refs == 0) Chunk::of(s_)->retire_slot();
    }

    Slot* s_ = nullptr;
  };

  // --------------------------------------------------------------- WeakPtr
  // Non-owning and non-counting: copying/destroying one costs nothing.
  // NOT a safe weak pointer -- there is no expiry check. Use it for borrowing
  // inside a scope where the originating Ptr is known to outlive it.
  class WeakPtr {
   public:
    WeakPtr() noexcept = default;
    WeakPtr(const Ptr& p) noexcept : s_(p.s_) {}
    // Binding to a temporary Ptr would dangle immediately, so forbid it.
    WeakPtr(Ptr&&) = delete;

    Ptr lock() const noexcept { return Ptr(*this); }

    const T* get() const noexcept { return reinterpret_cast<const T*>(s_); }
    const T& operator*() const noexcept { return *get(); }
    const T* operator->() const noexcept { return get(); }
    explicit operator bool() const noexcept { return s_ != nullptr; }
    std::uint32_t use_count() const noexcept { return s_ ? s_->refs : 0; }

    friend bool operator==(const WeakPtr& a, const WeakPtr& b) noexcept { return a.s_ == b.s_; }
    friend bool operator!=(const WeakPtr& a, const WeakPtr& b) noexcept { return a.s_ != b.s_; }

   private:
    friend Ptr;
    Slot* s_ = nullptr;
  };

  // ------------------------------------------------------------- Allocator
  class Allocator {
   public:
    explicit Allocator(const Options& opt) : opt_(opt) {
      if (opt_.refill_batch == 0) opt_.refill_batch = 1;
      free_.reserve(opt_.max_cached_chunks + opt_.refill_batch);
    }
    Allocator(const Allocator&) = delete;
    Allocator& operator=(const Allocator&) = delete;

    ~Allocator() {
      if (!opt_.unmap_on_destroy) return;
      for (Chunk* c = active_; c;) {
        Chunk* n = c->next;
        unmap_chunk(c);
        c = n;
      }
      for (void* p : free_) unmap_chunk(p);
    }

    // Hot path: hand out the next raw slot (refs/storage uninitialised).
    Slot* allocate() {
      if (__builtin_expect(next_ == end_, 0)) advance();
      ++cur_->live;
      return next_++;
    }

    // Roll back the most recent allocate() (used if T's constructor throws).
    void undo_allocate() noexcept {
      --next_;
      --cur_->live;
    }

    // Called by Chunk::retire_slot when the last live slot of a chunk dies.
    void release_chunk(Chunk* c) noexcept {
      unlink(c);
      --in_use_;
      if (free_.size() < opt_.max_cached_chunks) {
        free_.push_back(c);  // capacity reserved in the constructor
      } else {
        unmap_chunk(c);
      }
    }

    // Make sure `n` more slots can be allocated without touching the OS, and
    // pre-fault the memory. Intended for the 5-10ms pause before a burst.
    void reserve_slots(std::size_t n) {
      const std::size_t avail = static_cast<std::size_t>(end_ - next_);
      if (n <= avail) return;
      const std::size_t need = (n - avail + kSlotsPerChunk - 1) / kSlotsPerChunk;
      if (free_.size() >= need) return;
      const std::size_t missing = need - free_.size();
      free_.reserve(free_.size() + missing);
      unsigned char* base = static_cast<unsigned char*>(map_run(missing));
      for (std::size_t i = 0; i < missing; ++i) {
        prefault(base + i * ChunkBytes);
        free_.push_back(base + i * ChunkBytes);
      }
    }

    // Return cached chunks to the OS until at most `keep` remain.
    void trim(std::size_t keep = 0) noexcept {
      while (free_.size() > keep) {
        unmap_chunk(free_.back());
        free_.pop_back();
      }
    }

    Stats stats() const noexcept {
      Stats s = stats_;
      s.chunks_in_use = in_use_;
      s.chunks_cached = free_.size();
      return s;
    }

   private:
    friend Chunk;

    void advance() {
      if (cur_) {
        Chunk* old = cur_;
        cur_ = nullptr;  // next_ == end_ still holds, so a failure below is retryable
        if (--old->live == 0) release_chunk(old);  // owner hold dropped
      }
      Chunk* c = take_chunk();
      c->live = 1;  // the "currently being filled" hold
      link(c);
      ++in_use_;
      cur_ = c;
      next_ = c->slots();
      end_ = next_ + kSlotsPerChunk;
    }

    Chunk* take_chunk() {
      void* base;
      if (!free_.empty()) {
        base = free_.back();
        free_.pop_back();
        ++stats_.chunk_reuses;
      } else {
        base = map_run(opt_.refill_batch);
        for (std::size_t i = 1; i < opt_.refill_batch; ++i)
          free_.push_back(static_cast<unsigned char*>(base) + i * ChunkBytes);
      }
      return ::new (base) Chunk{this, nullptr, nullptr, 0};
    }

    void link(Chunk* c) noexcept {
      c->prev = nullptr;
      c->next = active_;
      if (active_) active_->prev = c;
      active_ = c;
    }
    void unlink(Chunk* c) noexcept {
      if (c->prev) c->prev->next = c->next; else active_ = c->next;
      if (c->next) c->next->prev = c->prev;
    }

    // Map n contiguous ChunkBytes-aligned chunks with a single mmap (+ trims).
    void* map_run(std::size_t n) {
      const std::size_t len = (n + 1) * ChunkBytes;
      void* raw = ::mmap(nullptr, len, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
      if (raw == MAP_FAILED) throw std::bad_alloc();
      ++stats_.mmap_calls;
      stats_.chunks_mapped += n;

      const auto a = reinterpret_cast<std::uintptr_t>(raw);
      const auto b = (a + ChunkBytes - 1) & ~(std::uintptr_t(ChunkBytes) - 1);
      const auto end = a + len;
      const auto bend = b + n * ChunkBytes;
      if (b > a) {
        ::munmap(raw, b - a);
        ++stats_.munmap_calls;
      }
      if (end > bend) {
        ::munmap(reinterpret_cast<void*>(bend), end - bend);
        ++stats_.munmap_calls;
      }
#ifdef MADV_HUGEPAGE
      if (opt_.use_huge_pages) ::madvise(reinterpret_cast<void*>(b), n * ChunkBytes, MADV_HUGEPAGE);
#endif
      return reinterpret_cast<void*>(b);
    }

    void unmap_chunk(void* c) noexcept {
      ::munmap(c, ChunkBytes);
      ++stats_.munmap_calls;
    }

    static void prefault(void* p) noexcept {
#ifdef MADV_POPULATE_WRITE
      if (::madvise(p, ChunkBytes, MADV_POPULATE_WRITE) == 0) return;
#endif
      volatile unsigned char* c = static_cast<volatile unsigned char*>(p);
      for (std::size_t off = 0; off < ChunkBytes; off += 4096) c[off] = 0;
    }

    Options opt_;
    Stats stats_;
    std::size_t in_use_ = 0;
    std::vector<void*> free_;  // LIFO recycle cache (warmest chunk on top)
    Chunk* active_ = nullptr;  // list of chunks that hold live slots
    Chunk* cur_ = nullptr;     // chunk currently being bump-filled
    Slot* next_ = nullptr;
    Slot* end_ = nullptr;
  };

  // --------------------------------------------------------------- Factory
  class Factory {
   public:
    explicit Factory(const Options& opt = Options{}) : alloc_(opt) {}
    // Chunks keep a back-pointer to the Allocator, so the Factory must not move.
    Factory(const Factory&) = delete;
    Factory& operator=(const Factory&) = delete;

    template <class... Args>
    Ptr make(Args&&... args) {
      Slot* s = alloc_.allocate();
      try {
        void* p = static_cast<void*>(s->storage);
        if constexpr (std::is_constructible_v<T, Args&&...>)
          ::new (p) T(std::forward<Args>(args)...);
        else
          ::new (p) T{std::forward<Args>(args)...};  // aggregates in C++17
      } catch (...) {
        alloc_.undo_allocate();
        throw;
      }
      s->refs = 1;
      return Ptr(s);
    }
    template <class... Args>
    Ptr create(Args&&... args) { return make(std::forward<Args>(args)...); }

    void reserve(std::size_t n_slots) { alloc_.reserve_slots(n_slots); }
    void trim(std::size_t keep_chunks = 0) noexcept { alloc_.trim(keep_chunks); }
    Stats stats() const noexcept { return alloc_.stats(); }
    Allocator& allocator() noexcept { return alloc_; }

   private:
    Allocator alloc_;
  };
};

} //?namespace rtl
} //?namespace scabbard
